values.value:
[
  [
    {
      "fieldName": "ucinn_ascendv2__Payment_Method__c",
      "toolTip": "Determines how the Payment record will be created and corresponding validation rules from regular GP. Value to be stored on the Payment Amount field of the Payment record will either be Gift Amount only or Gift Amount + Non-Gift Amount.",
      "customFieldParams": {
        "type": "picklist",
        "label": "Payment Method",
        "customPicklistValuesString": [
          "Legacy",
          "Gift Amount",
          "Gift Amount + Non-Gift Amount"
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Hard_Soft_Credit_Calculation_Type__c",
      "toolTip": "Only applies to non-Legacy Payment Methods. Determines how Hard and Soft Credits are calculated: Either Payment Amount (Gift + Non-Gift) OR Gift Amount Payer Hard Credit / Non-Gift Amount Payer Soft Credit / Payment Amount Relationship Soft Credit.",
      "customFieldParams": {
        "type": "picklist",
        "label": "Hard/Soft Credit Calculation Type",
        "customPicklistValuesString": [
          "Legacy",
          "Payment Amount",
          "Gift Amount / Non-Gift Amount / Payment Amount"
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Auto_Calculation_Setting__c",
      "toolTip": "A mapping of ascend transaction types to the autocalculation status. For example, \"{ \"{ascend transaction type}\" : \"{Enabled or Disabled}\" }\"",
      "jsonFieldParams": {
        "label": "Transaction Types for auto-calculation",
        "type": "object",
        "title": "Auto Calculation Setting",
        "keyLabel": "Transaction Type",
        "valueLabel": "Auto Calculation Setting",
        "jsonKeysToValueList": [
          {
            "key": "Outright Gift",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Recurring Gift",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Recurring Gift Payment",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Pledge",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Pledge Payment",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Matching Gift",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          },
          {
            "key": "Matching Gift Payment",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Enabled",
                "Disabled",
                "Provide Option"
              ]
            }
          }
        ]
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Allow_Non_Gift_Amount_to_Pay_Installment__c",
      "toolTip": "When checked, all payment method in Gift Processing Setting CMT will adhere to the method selected (just like in the case of outright gift, for example). Payment method of Legacy will allow non-gift amount to pay down the pledge. If unchecked, use current approach, which is don't apply non gift amount to payment when making a pledge payment.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Allow Non Gift Amount to Pay Installment"
      }
    }
  ]
]

{
"objectApiName": "ucinn_ascendv2__Gift_Processing_Setting__mdt",
"title": "Payment Amount Calculation Settings",
"helpText": "Set the behavior of Gift Processing for the interaction between the Amount fields on the Payment Object"
}
